sys_generative_ai_custom_llm_transformer.request_transformer:
(function(inputs) {
    var promptData = inputs.prompt_data;
    var prompt = promptData.prompt || '';

    var typeMatch = prompt.match(/TYPE:(.*)/);
    var instructionsMatch = prompt.match(/INSTRUCTIONS:(.*)/);
    var stateMatch = prompt.match(/STATE:([\s\S]*)/);

    var questionType = typeMatch ? typeMatch[1].trim() : 'noul';
    var instructions = instructionsMatch ? instructionsMatch[1].trim() : prompt;
    var state = stateMatch ? stateMatch[1].trim() : prompt;

    var body = {
        model: 'jev-latest',
        state: state,
        questions: {
            answer: {
                type: questionType,
                instructions: instructions
            }
        }
    };

    var headers = {};

    return {
        body: body,
        headers: headers
    };
})(inputs);

sys_generative_ai_custom_llm_transformer.response_transformer:
(function(inputs) {
    var responseBody = JSON.parse(inputs.response_body);
    var responseTexts = [];

    var answers = responseBody.answers || {};
    var keys = Object.keys(answers);
    for (var i = 0; i < keys.length; i++) {
        var key = keys[i];
        responseTexts.push(key + ': ' + JSON.stringify(answers[key]));
    }

    if (responseTexts.length === 0) {
        responseTexts.push('(no answer returned by Jev)');
    }

    return responseTexts;
})(inputs);
